47: /** Implementation of a {@link DataTypeFactory}. */
48: @Internal
49: final class DataTypeFactoryImpl implements DataTypeFactory {
50: 
51:     private final LogicalTypeResolver resolver = new LogicalTypeResolver();
52: 
53:     private final ClassLoader classLoader;
54: 
55:     private final Supplier<ExecutionConfig> executionConfig;
56: 
57:     DataTypeFactoryImpl(
58:             ClassLoader classLoader,
59:             ReadableConfig config,
60:             @Nullable ExecutionConfig executionConfig) {
61:         this.classLoader = classLoader;
62:         this.executionConfig =
63:                 createSerializerExecutionConfig(classLoader, config, executionConfig);
64:     }
65: 
66:     @Override
67:     public DataType createDataType(AbstractDataType<?> abstractDataType) {
68:         if (abstractDataType instanceof DataType) {
69:             return (DataType) abstractDataType;
70:         } else if (abstractDataType instanceof UnresolvedDataType) {
71:             return ((UnresolvedDataType) abstractDataType).toDataType(this);
72:         }
73:         throw new ValidationException("Unsupported abstract data type.");
74:     }
75: 
76:     @Override
77:     public DataType createDataType(String typeString) {
78:         return fromLogicalToDataType(createLogicalType(typeString));
79:     }
80: 
81:     @Override
82:     public DataType createDataType(UnresolvedIdentifier identifier) {
83:         return fromLogicalToDataType(createLogicalType(identifier));
84:     }
85: 
86:     @Override
87:     public <T> DataType createDataType(Class<T> clazz) {
88:         return DataTypeExtractor.extractFromType(this, clazz);
89:     }
90: 
91:     @Override
92:     public <T> DataType createDataType(TypeInformation<T> typeInfo) {
93:         return TypeInfoDataTypeConverter.toDataType(this, typeInfo);
94:     }
95: 
96:     @Override
97:     public <T> DataType createRawDataType(Class<T> clazz) {
98:         // we assume that a RAW type is nullable by default
99:         return DataTypes.RAW(clazz, new KryoSerializer<>(clazz, executionConfig.get()));
100:     }
101: 
102:     @Override
103:     public <T> DataType createRawDataType(TypeInformation<T> typeInfo) {
104:         // we assume that a RAW type is nullable by default
105:         return DataTypes.RAW(
106:                 typeInfo.getTypeClass(), typeInfo.createSerializer(executionConfig.get()));
107:     }
108: 
109:     @Override
110:     public LogicalType createLogicalType(String typeString) {
111:         final LogicalType parsedType = LogicalTypeParser.parse(typeString, classLoader);
112:         return parsedType.accept(resolver);
113:     }
114: 
115:     @Override
116:     public LogicalType createLogicalType(UnresolvedIdentifier identifier) {
117:         if (!identifier.getDatabaseName().isPresent()) {
118:             return createLogicalType(identifier.getObjectName());
119:         }
120:         return resolveType(identifier);
121:     }
