177:     /** Resolves all {@link UnresolvedUserDefinedType}s. */
178:     private class LogicalTypeResolver extends LogicalTypeDuplicator {
179: 
180:         @Override
181:         protected LogicalType defaultMethod(LogicalType logicalType) {
182:             if (logicalType.is(LogicalTypeRoot.UNRESOLVED)) {
183:                 final UnresolvedUserDefinedType unresolvedType =
184:                         (UnresolvedUserDefinedType) logicalType;
185:                 return resolveType(unresolvedType.getUnresolvedIdentifier())
186:                         .copy(unresolvedType.isNullable());
187:             }
188:             return logicalType;
189:         }
190:     }
191: 
192:     private LogicalType resolveType(UnresolvedIdentifier identifier) {
193:         assert identifier != null;
194:         // TODO validate implementation class of structured types when converting from LogicalType
195:         //  to DataType
196:         throw new TableException("User-defined types are not supported yet.");
197:     }
198: }
